package com.multitenanterp.payroll;
import com.multitenanterp.platform.tenant.TenantContext;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PayrollApprovalWorkflowIntegrationTest{
 private JdbcClient db;private PayrollCalculationService service;private UUID tenant,other,run;
 @BeforeEach void setup(){tenant=UUID.randomUUID();other=UUID.randomUUID();run=UUID.randomUUID();JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1");db=JdbcClient.create(ds);schema();db.sql("INSERT INTO payroll_run(id,tenant_id,payroll_year,payroll_month,status,calculated_at,calculated_by) VALUES(?,?,2026,9,'CALCULATED',CURRENT_TIMESTAMP,'maker@example.com')").params(run,tenant).update();service=new PayrollCalculationService(db);TenantContext.set(tenant);}
 @AfterEach void clear(){TenantContext.clear();}
 @Test void enforcesMakerCheckerAndRecordsTheCompleteWorkflow(){service.startReview(2026,9,"maker@example.com");assertThatThrownBy(()->service.approve(2026,9,"maker@example.com")).isInstanceOf(ResponseStatusException.class).hasMessageContaining("Maker cannot approve");assertThat(service.approve(2026,9,"checker@example.com").status()).isEqualTo("APPROVED");assertThat(service.lock(2026,9,"checker@example.com").status()).isEqualTo("LOCKED");PayrollRun reopened=service.reopen(2026,9,"Correct bank details","admin@example.com");assertThat(reopened.status()).isEqualTo("UNDER_REVIEW");assertThat(reopened.transitions()).extracting(PayrollRunTransition::toStatus).containsExactly("UNDER_REVIEW","APPROVED","LOCKED","UNDER_REVIEW");service.approve(2026,9,"checker@example.com");service.lock(2026,9,"checker@example.com");PayrollRun reversed=service.reverse(2026,9,"Replacement run required","admin@example.com");assertThat(reversed.status()).isEqualTo("REVERSED");assertThat(reversed.reversalReason()).isEqualTo("Replacement run required");assertThat(reversed.transitions()).hasSize(7);}
 @Test void rejectsOutOfOrderAndCrossTenantTransitions(){assertThatThrownBy(()->service.lock(2026,9,"checker@example.com")).isInstanceOf(ResponseStatusException.class).hasMessageContaining("Only approved");TenantContext.set(other);assertThatThrownBy(()->service.approve(2026,9,"checker@example.com")).isInstanceOf(ResponseStatusException.class).hasMessageContaining("not found");}
 private void schema(){db.sql("CREATE TABLE tenant(id UUID PRIMARY KEY)").update();db.sql("INSERT INTO tenant VALUES(?),(?)").params(tenant,other).update();db.sql("CREATE TABLE payroll_run(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,payroll_year INT,payroll_month INT,status VARCHAR(20),calculated_at TIMESTAMP WITH TIME ZONE,calculated_by VARCHAR(255),review_started_at TIMESTAMP WITH TIME ZONE,review_started_by VARCHAR(255),approved_at TIMESTAMP WITH TIME ZONE,approved_by VARCHAR(255),locked_at TIMESTAMP WITH TIME ZONE,locked_by VARCHAR(255),reversed_at TIMESTAMP WITH TIME ZONE,reversed_by VARCHAR(255),reversal_reason VARCHAR(1000),UNIQUE(tenant_id,payroll_year,payroll_month),UNIQUE(id,tenant_id))").update();db.sql("CREATE TABLE payroll_employee_result(id UUID PRIMARY KEY,tenant_id UUID,payroll_run_id UUID,employment_id UUID,salary_assignment_id UUID,gross_pay NUMERIC(14,2),deductions NUMERIC(14,2),employer_contributions NUMERIC(14,2),net_pay NUMERIC(14,2),ctc NUMERIC(14,2),period_days NUMERIC,eligible_days NUMERIC,unpaid_leave_days NUMERIC,absent_days NUMERIC,payable_days NUMERIC,proration_factor NUMERIC,overtime_minutes INT)").update();db.sql("CREATE TABLE payroll_component_result(id UUID,tenant_id UUID,payroll_employee_result_id UUID,salary_component_id UUID,component_code VARCHAR,component_name VARCHAR,component_type VARCHAR,amount NUMERIC,sequence_number INT)").update();db.sql("CREATE TABLE payroll_adjustment_result(id UUID,tenant_id UUID,payroll_employee_result_id UUID,source_type VARCHAR,source_id UUID,code VARCHAR,name VARCHAR,result_type VARCHAR,amount NUMERIC)").update();db.sql("CREATE TABLE payroll_exception(id UUID,tenant_id UUID,payroll_run_id UUID,employment_id UUID,exception_code VARCHAR,severity VARCHAR,message VARCHAR,resolved BOOLEAN,resolution_comment VARCHAR,resolved_by VARCHAR,resolved_at TIMESTAMP WITH TIME ZONE)").update();db.sql("CREATE TABLE payroll_run_transition(id UUID PRIMARY KEY,transition_sequence BIGINT GENERATED BY DEFAULT AS IDENTITY,tenant_id UUID,payroll_run_id UUID,from_status VARCHAR,to_status VARCHAR,reason VARCHAR,acted_by VARCHAR,acted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP)").update();}
}
